//! Compiles the Slint UI and, for Windows targets, embeds the application icon.
//!
//! `assets/icon.ico` (generated by `scripts/make-icons.py`) gives the `.exe` its icon in
//! Explorer. The titlebar and taskbar icon comes from `assets/icon.png`, set on each Slint
//! window in `ui/app.slint`, because winit registers its window class without one.
//!
//! The target OS is read from `CARGO_CFG_TARGET_OS` at run time. A build script runs on the
//! host, so `#[cfg(windows)]` would miss Windows binaries cross-compiled from Linux. A missing
//! resource compiler must not fail the build; a Slint compile error still does.

fn main() {
    // The app is dark only, so the standard widgets must be dark whatever the system theme is.
    // The `-dark` style fixes the color scheme for every window from the first frame.
    // Debug info lets the UI harness find elements through Slint's testing API; other builds
    // leave it out.
    let ui_harness = std::env::var_os("CARGO_FEATURE_UI_HARNESS").is_some();
    slint_build::compile_with_config(
        "ui/app.slint",
        slint_build::CompilerConfiguration::new()
            .with_style("fluent-dark".to_string())
            .with_debug_info(ui_harness),
    )
    .unwrap();

    println!("cargo:rerun-if-env-changed=CARGO_CFG_TARGET_OS");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows") {
        embed_icon();
    }
}

/// Embeds `assets/icon.ico` as the executable's Windows icon resource.
///
/// Kept identical to `apps/pleochroma-worker/build.rs`'s `embed_icon`; build scripts
/// cannot share code across packages, so edits must be mirrored in both.
fn embed_icon() {
    println!("cargo:rerun-if-changed=assets/icon.ico");
    let mut res = winresource::WindowsResource::new();
    res.set_icon("assets/icon.ico");
    if let Err(e) = res.compile() {
        println!(
            "cargo:warning=could not embed the application icon ({e}); the binary will build without one"
        );
    }
}
